def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = []

    # Identify 3x3 markers: eight 3s around a central 2.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr, cc in ((r-1,c-1), (r-1,c), (r-1,c+1),
                               (r,c-1), (r,c+1),
                               (r+1,c-1), (r+1,c), (r+1,c+1))
            ):
                centers.append((r, c))

    for r, c in centers:
        # The 2-line through the marker determines the perpendicular beam.
        horizontal_line = (
            (c >= 2 and grid[r][c-2] == 2) or
            (c + 2 < w and grid[r][c+2] == 2)
        )
        vertical_line = (
            (r >= 2 and grid[r-2][c] == 2) or
            (r + 2 < h and grid[r+2][c] == 2)
        )

        if horizontal_line:
            dr, dc = 1, 0       # beam runs vertically
        elif vertical_line:
            dr, dc = 0, 1       # beam runs horizontally
        else:
            continue

        # Extend the beam in both directions, marking intervening empty cells.
        for sign in (-1, 1):
            rr, cc = r + sign * dr, c + sign * dc
            while 0 <= rr < h and 0 <= cc < w:
                if grid[rr][cc] == 0:
                    out[rr][cc] = 1
                elif grid[rr][cc] == 2:
                    # At a crossing, draw the eight surrounding cells.
                    for ar in range(rr - 1, rr + 2):
                        for ac in range(cc - 1, cc + 2):
                            if (0 <= ar < h and 0 <= ac < w and
                                (ar, ac) != (rr, cc) and grid[ar][ac] != 3):
                                out[ar][ac] = 1
                rr += sign * dr
                cc += sign * dc

    return out
